<?php
namespace App\Http\Controllers;
use App\Models\CourseClass; use App\Models\PlatformAnnouncement; use App\Models\Program; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class CourseClassController extends Controller {
 public function dashboard(Request $request): View { $classes=$request->user()->taughtClasses()->where('is_archived',false)->withCount('students')->latest()->get(); $programs=Program::with('department')->orderBy('name')->get(); $platformAnnouncements=PlatformAnnouncement::where('display_type','card')->with('author:id,name')->latest()->take(5)->get(); return view('lecturer.dashboard',compact('classes','programs','platformAnnouncements')); }
 public function store(Request $request): RedirectResponse { $data=$request->validate(['program_id'=>['nullable','exists:programs,id'],'course_title'=>['required','string','max:255'],'course_code'=>['required','string','max:50'],'department'=>['required','string','max:120'],'academic_year'=>['required','regex:/^\\d{4}\\/\\d{4}$/'],'semester'=>['required','string','max:30']]); $request->user()->taughtClasses()->create($data); return back()->with('status','Class created.'); }
 public function show(Request $request, CourseClass $courseClass): View { abort_unless($courseClass->lecturer_id===$request->user()->id,403); $students=$courseClass->students()->with('studentProfile')->when($request->department,fn($q,$d)=>$q->whereHas('studentProfile',fn($p)=>$p->where('department',$d)))->when($request->program,fn($q,$p)=>$q->whereHas('studentProfile',fn($s)=>$s->where('program_name',$p)))->get(); return view('lecturer.classes.show',['courseClass'=>$courseClass->load('announcements'),'students'=>$students]); }
 public function archive(Request $request, CourseClass $courseClass): RedirectResponse { abort_unless($courseClass->lecturer_id===$request->user()->id,403); $courseClass->update(['is_archived'=>true]); return redirect()->route('lecturer.dashboard')->with('status','Class archived.'); }
}
